// Example instrumentation sketch (Node.js-like)
import { trace, context, propagation } from '@opentelemetry/api';
const tracer = trace.getTracer('cnpa');
app.use((req, res, next) => {
  const span = tracer.startSpan(`HTTP ${req.method} ${req.path}`);
  context.with(trace.setSpan(context.active(), span), () => {
    res.on('finish', () => span.end());
    next();
  });
});

// DB call (child span)
db.query('SELECT ...', (err, rows) => {
  // span = tracer.startSpan('DB Query') as needed
  // end span after query
});

// Kafka publish (child span)
const msg = { value: '...', headers: { traceparent: traceContext } };
producer.send({ topic: 'events', messages: [msg] });
```

